<?php
declare(strict_types=1);
namespace app\common\service\app\aigc_copywriting;
final class CopywritingDocument {
 public static function normalize(array $d):array { $d+=['schema_version'=>1,'page'=>[],'fields'=>[],'prompt'=>['system_prompt'=>'','user_template'=>''],'result'=>['mode'=>'article'],'model'=>['selection_mode'=>'user','allowed_model_ids'=>[]],'publish_targets'=>['pc','h5','mp-weixin'],'extensions'=>[]];$d['page']+=['nodes'=>[]];return $d; }
 public static function catalog():array {return json_decode(file_get_contents(dirname(__DIR__,4).'/apps/aigc_copywriting/contracts/catalog.json'),true,512,JSON_THROW_ON_ERROR);}
 public static function validate(array $input,array $targets=[]):array {$d=self::normalize($input);$e=[];$err=function($code,$path,$message='')use(&$e){$e[]=['code'=>$code,'path'=>$path,'message'=>$message?:$code];};if($d['schema_version']!==1)$err('SCHEMA_VERSION','schema_version','不支持的配置版本');$ids=[];$keys=[];foreach($d['fields'] as $f){if(!preg_match('/^[a-z][a-z0-9_]{0,63}$/D',(string)($f['key']??'')))$err('FIELD_KEY',$f['id']??'');if(isset($keys[$f['key']??'']))$err('DUPLICATE_KEY',$f['id']??'','字段变量重复');if(isset($ids[$f['id']??'']))$err('DUPLICATE_ID',$f['id']??'');$keys[$f['key']??'']=true;$ids[$f['id']??'']=true;if(!in_array($f['type']??'',self::catalog()['field_types'],true))$err('FIELD_TYPE',$f['id']??'');}$nodeIds=[];$walk=function($nodes,$depth=0)use(&$walk,&$nodeIds,$ids,$err){if($depth>16)throw new \InvalidArgumentException('组件嵌套过深');foreach($nodes as $n){$id=$n['id']??'';if(!$id||isset($nodeIds[$id]))$err('NODE_ID',$id);$nodeIds[$id]=true;if(!in_array($n['name']??'',self::catalog()['components'],true))$err('UNKNOWN_COMPONENT',$id);if(($n['name']??'')==='cw-field'&&!isset($ids[$n['content']['field_id']??'']))$err('FIELD_BINDING',$id);$walk($n['children']??[],$depth+1);}};$walk($d['page']['nodes']);foreach(['system_prompt','user_template']as $k){preg_match_all('/{{\s*([a-z][a-z0-9_]*)\s*}}/u',$d['prompt'][$k]??'',$m);foreach($m[1]as $key)if(!isset($keys[$key]))$err('UNKNOWN_VARIABLE',$key,'提示词引用了不存在的字段');}return array_merge($e,CopywritingStyleCompiler::validate($d,$targets));}
 public static function assertValid(array $d,array $targets=[]):void {$e=self::validate($d,$targets);if($e)throw new \InvalidArgumentException($e[0]['message'].'：'.$e[0]['path']);}
 public static function publicDocument(array $d):array {unset($d['prompt']);return $d;}
}
